160	pub fn run(db: Arc<VectorDB>, addr: &str) -> io::Result<()> {
161	    let listener = TcpListener::bind(addr)?;
162	    let stats = RequestStats::from_env().map(Arc::new);
163	    let split_cached_search_response = env_flag(SPLIT_CACHED_SEARCH_RESPONSE_ENV);
164	    let post_write_spin = env_u64(POST_WRITE_SPIN_US_ENV);
165	    let close_after_cached_search = env_flag(CLOSE_AFTER_CACHED_SEARCH_ENV);
166	    let early_cached_search_headers = env_flag_default_true(EARLY_CACHED_SEARCH_HEADERS_ENV);
167	    let early_cached_search_partial_read_bytes =
168	        usize::try_from(env_u64(EARLY_CACHED_SEARCH_PARTIAL_READ_BYTES_ENV)).unwrap_or(0);
169	
170	    loop {
171	        let (stream, _) = listener.accept()?;
172	        let db = db.clone();
173	        let stats = stats.clone();
174	        thread::spawn(move || {
175	            let _ = handle_connection(
176	                stream,
177	                db,
178	                stats,
179	                split_cached_search_response,
180	                post_write_spin,
181	                close_after_cached_search,
182	                early_cached_search_headers,
183	                early_cached_search_partial_read_bytes,
184	            );
185	        });
186	    }
187	}
