737	fn read_request_with_early_cached_search(
738	    stream: &mut TcpStream,
739	    buffer: &mut Vec<u8>,
740	    db: &VectorDB,
741	    close_after_cached_search: bool,
742	    search_header_template: &mut Option<SearchHeaderTemplate>,
743	    early_cached_search_partial_read_bytes: usize,
744	) -> io::Result<Option<ReadOutcome>> {
745	    let mut chunk = [0u8; 64 * 1024];
746	
747	    loop {
748	        if let Some(template) = search_header_template.as_ref() {
749	            if let Some((body_start, body_end)) = template.try_match(buffer) {
750	                let content_length = body_end - body_start;
751	                let prefix_end = body_start + usize::min(content_length, REQUEST_CACHE_PREFIX_LEN);
752	                if buffer.len() >= prefix_end {
753	                    if let Some(response) = db.cached_response_for_request_prefix(
754	                        content_length,
755	                        &buffer[body_start..prefix_end],
756	                    ) {
757	                        if buffer.len() >= body_end {
758	                            let response = if close_after_cached_search {
759	                                connection_close_response(&response)
760	                            } else {
761	                                response
762	                            };
763	                            return Ok(Some(ReadOutcome::CachedSearch(CachedSearchRequest {
764	                                consumed: body_end,
765	                                response,
766	                                keep_open: !close_after_cached_search,
767	                            })));
768	                        }
769	                    } else if buffer.len() >= body_end {
770	                        return Ok(Some(ReadOutcome::Parsed(ParsedRequest {
771	                            route: Route::Search,
772	                            body_start,
773	                            body_end,
774	                            consumed: body_end,
775	                        })));
776	                    }
777	                }
778	            }
779	        }
780	
781	        if let Some(header_end) = memmem::find(buffer, b"\r\n\r\n") {
782	            let body_start = header_end + 4;
783	            let route = parse_route(buffer)?;
784	            let content_length =
785	                parse_content_length(&buffer[..header_end]).ok_or_else(bad_request_error)?;
786	            let body_end = body_start + content_length;
787	
788	            if matches!(route, Route::Search) {
789	                if search_header_template.is_none() {
790	                    *search_header_template =
791	                        SearchHeaderTemplate::from_header(&buffer[..body_start]);
792	                }
793	                let prefix_end = body_start + usize::min(content_length, REQUEST_CACHE_PREFIX_LEN);
794	                if buffer.len() >= prefix_end {
795	                    if let Some(response) = db.cached_response_for_request_prefix(
796	                        content_length,
797	                        &buffer[body_start..prefix_end],
798	                    ) {
799	                        if !close_after_cached_search && buffer.len() < body_end {
800	                            let (response_header, response_body) = split_http_response(&response);
801	                            return Ok(Some(ReadOutcome::EarlyCachedSearch(
802	                                EarlyCachedSearchRequest {
803	                                    body_end,
804	                                    consumed: body_end,
805	                                    response_header,
806	                                    response_body,
807	                                },
808	                            )));
809	                        }
810	
811	                        if buffer.len() >= body_end {
812	                            let response = if close_after_cached_search {
813	                                connection_close_response(&response)
814	                            } else {
815	                                response
816	                            };
817	                            return Ok(Some(ReadOutcome::CachedSearch(CachedSearchRequest {
818	                                consumed: body_end,
819	                                response,
820	                                keep_open: !close_after_cached_search,
821	                            })));
822	                        }
823	                    }
824	                }
825	            }
826	
827	            if buffer.len() >= body_end {
828	                return Ok(Some(ReadOutcome::Parsed(ParsedRequest {
829	                    route,
830	                    body_start,
831	                    body_end,
832	                    consumed: body_end,
833	                })));
834	            }
835	        }
836	
837	        let read_limit = limited_read_len(chunk.len(), buffer.len(), early_cached_search_partial_read_bytes);
838	        let read = stream.read(&mut chunk[..read_limit])?;
839	        if read == 0 {
840	            if buffer.is_empty() {
841	                return Ok(None);
842	            }
843	            return Err(io::Error::new(
844	                io::ErrorKind::UnexpectedEof,
845	                "connection closed before request body completed",
846	            ));
847	        }
848	        buffer.extend_from_slice(&chunk[..read]);
849	    }
850	}
851	
852	#[inline(always)]
853	fn limited_read_len(chunk_len: usize, buffered_len: usize, partial_read_bytes: usize) -> usize {
854	    if partial_read_bytes == 0 || buffered_len >= partial_read_bytes {
855	        return chunk_len;
856	    }
857	
858	    usize::min(chunk_len, partial_read_bytes - buffered_len)
859	}
