861	fn finish_request_body(
862	    stream: &mut TcpStream,
863	    buffer: &mut Vec<u8>,
864	    body_end: usize,
865	) -> io::Result<()> {
866	    let mut chunk = [0u8; 64 * 1024];
867	    while buffer.len() < body_end {
868	        let read = stream.read(&mut chunk)?;
869	        if read == 0 {
870	            return Err(io::Error::new(
871	                io::ErrorKind::UnexpectedEof,
872	                "connection closed before request body completed",
873	            ));
874	        }
875	        buffer.extend_from_slice(&chunk[..read]);
876	    }
877	    Ok(())
878	}
